      if (f === 'kind') return `Предполагаемая роль поля — <b>${KL[C.kind]}</b>. ${C.kind === 'id' ? 'Название или почти все значения уникальны.' : C.kind === 'few' ? 'Разных чисел мало — проверьте, не коды ли это.' : C.kind === 'date' || C.kind === 'datetime' ? `${fmtD(C.fmts.reduce((s, x) => s + x[1], 0))} из ${fmtD(C.nn)} значений похожи на даты.` : C.kind === 'cat' ? 'Значений немного, они повторяются.' : C.kind === 'text' ? 'Значения почти не повторяются.' : ''}`;
