  /* ===================== Карта пропусков под блоком кода ===================== */
  function missMap(el) {
    const H = DATA.heat; if (!H) return;
    const draw = () => {
      const W = Math.max(300, Math.min(760, el.clientWidth || 640)), L = W < 460 ? 92 : 112, cw = (W - L - 8) / H.m.length, rh = 21, top = 8, n = H.cols.length;
      const hgt = top + n * rh + 54;
      let o = '';
      H.cols.forEach((c, j) => {
        const y = top + j * rh;
        o += `<text x="${L - 8}" y="${y + rh / 2 + 4}" text-anchor="end" font-size="${W < 460 ? 10.5 : 11.5}" style="fill: var(--ink-2); font-family: var(--mono)">${c}</text>`;
        H.m.forEach((row, i) => { const v = row[j]; o += `<rect x="${(L + i * cw).toFixed(2)}" y="${y + 1}" width="${(cw + .3).toFixed(2)}" height="${rh - 2}" style="fill: ${v > 0 ? `color-mix(in srgb, var(--bad) ${Math.round(12 + 88 * v / 100)}%, var(--surface))` : 'var(--sunk)'}"/>`; });
      });
      const by = top + n * rh + 10;
      const nar = W < 460, ax = nar ? 4 : L;
      o += `<text x="${ax}" y="${by + 12}" font-size="11" style="fill: var(--muted)">${nar ? 'строки по числу заказов →' : 'Число заказов: неизвестно → 0 → 1 … 10'}</text>`;
      o += `<defs><linearGradient id="fp-hg"><stop offset="0" style="stop-color: var(--sunk)"/><stop offset="1" style="stop-color: var(--bad)"/></linearGradient></defs><rect x="${ax}" y="${by + 22}" width="${nar ? 80 : 120}" height="8" rx="4" fill="url(#fp-hg)"/><text x="${ax + (nar ? 88 : 128)}" y="${by + 30}" font-size="11" style="fill: var(--muted)">${nar ? 'доля пропусков, 0–100%' : 'доля пропусков в полосе: 0 → 100%'}</text>`;
      el.innerHTML = `<figcaption>Дата последнего заказа пуста в строках с нулевым или неизвестным числом заказов</figcaption><svg viewBox="0 0 ${W} ${hgt}" width="${W}" height="${hgt}" role="img" aria-label="Карта пропусков: 10 столбцов учебной выгрузки, 40 полос по 301 строке, строки упорядочены по orders_q1. Дата последнего заказа пуста в 1 691 строке с нулём заказов и в 27 строках с неизвестным числом заказов. После замены кода −1 пропущенное число заказов занимает около половины первой полосы.">${o}</svg>`;
    };
    draw();
    if ('ResizeObserver' in window) { let lw = 0; new ResizeObserver(() => { const w = el.clientWidth; if (Math.abs(w - lw) > 4) { lw = w; draw(); } }).observe(el); }
  }

